local cloneref = cloneref or function(o) return o end
local Players = cloneref(game:GetService("Players"))
local TweenService = cloneref(game:GetService("TweenService"))
local UserInputService = cloneref(game:GetService("UserInputService"))

local Library = { Connections = {}, Alive = true, Animations = true }
local rgb = Color3.fromRGB
-- BloxStrikeAurora.lua's "Default": the Aurora palette with the darker surfaces it applies at load
Library.Theme = {
	["Window Background"] = rgb(22, 22, 23), ["Section Background"] = rgb(16, 16, 17), ["Inline"] = rgb(50, 50, 53),
	["Element"] = rgb(31, 31, 33), ["Element Hover"] = rgb(44, 44, 47), ["Border"] = rgb(44, 44, 47), ["Outline"] = rgb(4, 4, 5),
	["Dark Liner"] = rgb(12, 12, 13), ["Highlight"] = rgb(66, 66, 70), ["Text"] = rgb(200, 200, 200), ["Bright Text"] = rgb(255, 255, 255),
	["Dim Text"] = rgb(130, 130, 134), ["Risky"] = rgb(235, 80, 80), ["Accent"] = rgb(207, 31, 69), ["Shadow"] = rgb(0, 0, 0),
	["Good"] = rgb(90, 215, 130),
}
local themed = {}   -- { inst, prop, key }
function Library:AddToTheme(inst, map)
	for prop, key in map do
		if self.Theme[key] then
			pcall(function() inst[prop] = self.Theme[key] end)
			themed[#themed + 1] = { inst, prop, key }
		end
	end
end
-- recolour: win:Theme({ Accent = Color3, ... })
function Library:SetTheme(t)
	for k, v in t do self.Theme[k] = v end
	for _, e in themed do
		if e[1].Parent then pcall(function() e[1][e[2]] = self.Theme[e[3]] end) end
	end
end
Build.Theme = function(inst, map) Library:AddToTheme(inst, map) end
function Library:Connect(signal, fn)
	local c = signal:Connect(fn)
	self.Connections[#self.Connections + 1] = c
	return c
end
local function tween(inst, props, t, style, dir)
	local tw = TweenService:Create(inst, TweenInfo.new(t or 0.15, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
	tw:Play()
	return tw
end

-- ---- assets: font + icons (the PNGs are written once into Allison/assets and loaded with getcustomasset) ----
do
	local getasset = getcustomasset or getsynasset
	local b64 = (crypt and (crypt.base64decode or crypt.base64_decode or (crypt.base64 and crypt.base64.decode))) or base64decode or (base64 and base64.decode)
	pcall(function()
		for _, f in { "Allison", "Allison/assets" } do if makefolder and not (isfolder and isfolder(f)) then makefolder(f) end end
	end)
	if type(writefile) == "function" and getasset and b64 then
		for name, ic in Build.IconPng do
			pcall(function()
				local path = "Allison/assets/loader_" .. name .. ".png"
				writefile(path, b64(ic.b64))
				Build.IconAsset[name] = getasset(path)
			end)
		end
	end
	local function ubuntu(weight, fallback)
		local ok, f = pcall(function() return Font.new("rbxasset://fonts/families/Ubuntu.json", weight) end)
		return ok and f or Font.fromEnum(fallback)
	end
	Build.Font = ubuntu(Enum.FontWeight.Medium, Enum.Font.Ubuntu)
	Build.FontBold = ubuntu(Enum.FontWeight.Bold, Enum.Font.Ubuntu)
	Library.Font, Library.FontBold = Build.Font, Build.FontBold
end

-- ---- the square two-layer drop shadow of the menu (fx.shadow): a wide soft layer and a short dark one under the box ----
local SLICE_SQ = Rect.new(26, 26, 102, 102)
local function shadowLayer(inst, spread, transparency)
	local img = Instance.new("ImageLabel")
	img.Name = "Shadow"
	img.BackgroundTransparency, img.BorderSizePixel = 1, 0
	img.Image = Build.IconAsset.fx_shadowsq or ""
	img.ScaleType, img.SliceCenter, img.SliceScale = Enum.ScaleType.Slice, SLICE_SQ, spread / 24
	img.Position, img.Size = UDim2.fromOffset(-spread, -spread), UDim2.new(1, spread * 2, 1, spread * 2)
	img.ImageTransparency, img.ZIndex = transparency, 0
	img.ImageColor3 = Library.Theme.Shadow
	img.Parent = inst
	return img
end

-- ---- dragging / clicks ----
local function draggable(handle, target)
	local dragging, start, from
	Library:Connect(handle.InputBegan, function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging, start, from = true, i.Position, target.Position end
	end)
	Library:Connect(UserInputService.InputChanged, function(i)
		if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
			local d = i.Position - start
			target.Position = UDim2.new(from.X.Scale, from.X.Offset + d.X, from.Y.Scale, from.Y.Offset + d.Y)
		end
	end)
	Library:Connect(UserInputService.InputEnded, function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging = false end
	end)
end
local function click(inst, fn)
	local b = Instance.new("TextButton")
	b.Name = "Click"
	b.BackgroundTransparency, b.Text, b.AutoButtonColor = 1, "", false
	b.Size = UDim2.fromScale(1, 1)
	b.ZIndex = inst.ZIndex + 5
	b.Parent = inst
	if fn then Library:Connect(b.MouseButton1Click, fn) end
	return b
end

-- ---- the window ----
function Library:Injector(Data)
	Data = Data or {}
	local genv = (getgenv and getgenv()) or _G
	if genv.AllisonLoaderGui then pcall(function() genv.AllisonLoaderGui:Destroy() end) end
	local gui = Instance.new("ScreenGui")
	gui.Name = "AllisonLoader"
	gui.ResetOnSpawn, gui.IgnoreGuiInset, gui.DisplayOrder = false, true, 100001
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	pcall(function() if protectgui then protectgui(gui) end end)
	pcall(function() gui.Parent = (gethui and gethui()) or cloneref(game:GetService("CoreGui")) end)
	if not gui.Parent then gui.Parent = Players.LocalPlayer:WaitForChild("PlayerGui") end
	genv.AllisonLoaderGui = gui

	-- the window sits in a CanvasGroup with room for its shadow, so opening / closing fade and scale everything as one smooth layer
	local PAD = 34
	local canvas = Instance.new("CanvasGroup")
	canvas.Name = "Canvas"
	canvas.BackgroundTransparency, canvas.BorderSizePixel = 1, 0
	canvas.AnchorPoint, canvas.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
	canvas.GroupTransparency = 1
	canvas.Parent = gui
	local scale = Instance.new("UIScale")
	scale.Scale = 0.94
	scale.Parent = canvas
	local I = Build.Injector(canvas)
	local root = I.Root
	canvas.Size = UDim2.fromOffset(root.Size.X.Offset + PAD * 2, root.Size.Y.Offset + PAD * 2)
	root.AnchorPoint, root.Position = Vector2.new(0, 0), UDim2.fromOffset(PAD, PAD)
	shadowLayer(root, 26, 0.35)
	shadowLayer(root, 7, 0.45)
	I.title.Text = tostring(Data.Title or "allison")
	I.title2.Text = tostring(Data.Title2 or "loader")
	I.heading.Text = tostring(Data.Heading or "injector")
	I.user.Text = tostring(Data.User or Players.LocalPlayer.Name)
	I.title.TextXAlignment = Enum.TextXAlignment.Right
	-- the name row in the top edge: as wide as its two words
	task.defer(function()
		local w1, w2 = I.title.TextBounds.X, I.title2.TextBounds.X
		if w1 > 0 and w2 > 0 then
			I.title.Size = UDim2.fromOffset(w1, I.title.Size.Y.Offset)
			I.title.Position = UDim2.fromOffset(4, I.title.Position.Y.Offset)
			I.title2.Position = UDim2.fromOffset(4 + w1 + 4, I.title2.Position.Y.Offset)
			I.title2.Size = UDim2.fromOffset(w2, I.title2.Size.Y.Offset)
			local W = w1 + w2 + 12
			I.titleRow.Size = UDim2.fromOffset(W, I.titleRow.Size.Y.Offset)
			I.titleRow.Position = UDim2.new(0.5, -W / 2, 0, I.titleRow.Position.Y.Offset)
		end
	end)
	draggable(I.dragBar, canvas)
	draggable(I.titleRow, canvas)

	local win = { Gui = gui, Root = root, Parts = I }
	local alive = true
	-- Close(): fades out and shrinks (0.28 s), then the window is gone. It waits for that when the caller's thread can wait, so a
	-- script run right after it starts on a clean screen.
	local CLOSE_TIME = 0.28
	function win:Close(instant)
		if not alive then return end
		alive = false
		local function gone()
			for _, c in Library.Connections do pcall(function() c:Disconnect() end) end
			table.clear(Library.Connections)
			pcall(function() gui:Destroy() end)
			if genv.AllisonLoaderGui == gui then genv.AllisonLoaderGui = nil end
		end
		if instant or not Library.Animations then gone() return end
		pcall(function() canvas.Interactable = false end)
		tween(canvas, { GroupTransparency = 1 }, CLOSE_TIME, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		tween(scale, { Scale = 0.94 }, CLOSE_TIME, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		tween(canvas, { Position = canvas.Position + UDim2.fromOffset(0, 8) }, CLOSE_TIME, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		local ok = pcall(task.wait, CLOSE_TIME + 0.02)
		if ok then gone() else task.delay(CLOSE_TIME + 0.02, gone) end
	end
	-- close (×)
	local closeBtn = click(I.close, function()
		win:Close()
		if Data.OnClose then pcall(Data.OnClose) end
	end)
	Library:Connect(closeBtn.MouseEnter, function() tween(I.close, { TextColor3 = Library.Theme["Bright Text"] }) end)
	Library:Connect(closeBtn.MouseLeave, function() tween(I.close, { TextColor3 = Library.Theme["Dim Text"] }) end)

	-- status
	local KIND = { good = "Good", bad = "Risky", busy = "Accent" }
	function win:SetStatus(text, kind)
		text = tostring(text)
		local col = Library.Theme[KIND[kind] or "Dim Text"]
		if I.status.Text == text and I.status.TextColor3 == col then return end
		I.status.Text = text
		I.status.TextTransparency = 0.8
		tween(I.status, { TextTransparency = 0, TextColor3 = col }, 0.25)
	end

	-- the key field: a TextBox over the design's field, its placeholder in the design's colours
	I.fieldText.Visible = false
	local box = Instance.new("TextBox")
	box.Name = "Key"
	box.BackgroundTransparency, box.BorderSizePixel = 1, 0
	box.Size = UDim2.fromScale(1, 1)
	box.FontFace, box.TextSize = Build.Font, I.fieldText.TextSize
	box.TextColor3, box.PlaceholderColor3 = Library.Theme.Text, Library.Theme["Dim Text"]
	box.PlaceholderText = tostring(Data.Placeholder or "enter your key")
	box.Text, box.ClearTextOnFocus, box.ClipsDescendants = tostring(Data.Key or ""), false, true
	box.ZIndex = I.field.ZIndex + 2
	box.Parent = I.field
	local fieldStroke = I.field:FindFirstChildOfClass("UIStroke")
	Library:Connect(box.Focused, function() if fieldStroke then tween(fieldStroke, { Color = Library.Theme.Accent }) end end)
	Library:Connect(box.FocusLost, function() if fieldStroke then tween(fieldStroke, { Color = Library.Theme.Outline }) end end)
	local busy = false
	local function mask(k)
		if k == "" then return "none" end
		if #k <= 4 then return string.rep("•", #k) end
		return k:sub(1, 4) .. string.rep("•", math.min(#k - 4, 8))
	end
	local function keyNow() return (box.Text:gsub("%s", "")) end
	local function refreshKey()
		local k = keyNow()
		I.key.Text = mask(k)
		if not busy then win:SetStatus(k == "" and "no key" or "ready", k ~= "" and "good" or nil) end
	end
	Library:Connect(box:GetPropertyChangedSignal("Text"), refreshKey)
	function win:GetKey() return keyNow() end
	function win:SetKey(k) box.Text = tostring(k or "") end
	local fieldHome = I.field.Position
	function win:FlashField()
		if fieldStroke then
			fieldStroke.Color = Library.Theme.Risky
			task.delay(0.6, function() if fieldStroke.Parent then tween(fieldStroke, { Color = Library.Theme.Outline }, 0.4) end end)
		end
		-- a short shake left and right
		task.spawn(function()
			for _, dx in { -6, 5, -3, 2, 0 } do
				if not I.field.Parent then return end
				tween(I.field, { Position = fieldHome + UDim2.fromOffset(dx, 0) }, 0.05, Enum.EasingStyle.Sine)
				task.wait(0.05)
			end
			I.field.Position = fieldHome
		end)
	end

	-- the button: hover lightens it, a press flashes its edge
	I.buttonText.Text = tostring(Data.Button or "inject")
	local btnStroke = I.button:FindFirstChildOfClass("UIStroke")
	local btn = click(I.button)
	local press = Instance.new("UIScale")
	press.Parent = I.button
	Library:Connect(btn.MouseEnter, function() if not busy then tween(I.button, { BackgroundColor3 = Library.Theme["Element Hover"] }) end end)
	Library:Connect(btn.MouseLeave, function()
		tween(I.button, { BackgroundColor3 = Library.Theme.Element })
		tween(press, { Scale = 1 }, 0.3, Enum.EasingStyle.Back)
	end)
	Library:Connect(btn.MouseButton1Down, function()
		if btnStroke then btnStroke.Color = Library.Theme.Accent end
		tween(press, { Scale = 0.97 }, 0.08)
	end)
	Library:Connect(btn.MouseButton1Up, function()
		if btnStroke then tween(btnStroke, { Color = Library.Theme.Outline }, 0.3) end
		tween(press, { Scale = 1 }, 0.3, Enum.EasingStyle.Back)
	end)
	local busyGen = 0
	function win:SetBusy(b, text)
		busy = b and true or false
		busyGen += 1
		local gen = busyGen
		local base = text or (busy and "injecting" or tostring(Data.Button or "inject"))
		I.buttonText.Text = busy and (base .. "...") or base
		tween(I.buttonText, { TextColor3 = busy and Library.Theme["Dim Text"] or Library.Theme["Bright Text"] }, 0.2)
		if busy and not text then
			-- the dots run while it works
			task.spawn(function()
				local n = 0
				while busy and busyGen == gen and I.buttonText.Parent do
					n = n % 3 + 1
					I.buttonText.Text = base .. string.rep(".", n) .. string.rep(" ", 3 - n)
					task.wait(0.35)
				end
			end)
		end
		if not busy then refreshKey() end
	end

	-- the games
	local listLayout = Instance.new("UIListLayout")
	listLayout.Padding, listLayout.SortOrder = UDim.new(0, 6), Enum.SortOrder.LayoutOrder
	listLayout.Parent = I.list
	local rows, selected = {}, nil
	function win:Select(g)
		selected = g
		for other, r in rows do
			local on = other == g
			r.sel.Visible = on
			tween(r.Root, { BackgroundColor3 = on and Library.Theme["Element Hover"] or Library.Theme.Element })
			r.name.TextColor3 = on and Library.Theme["Bright Text"] or Library.Theme.Text
		end
		for part, v in { version = g.Version, build = g.Build, update = g.Update } do
			local t = I[part]
			local text = tostring(v or "-")
			if t.Text ~= text then
				t.Text = text
				t.TextTransparency = 1
				tween(t, { TextTransparency = 0 }, 0.3)
			end
		end
	end
	function win:Selected() return selected end
	for i, g in Data.Games or {} do
		local R = Build.GameRow(I.list)
		R.Root.LayoutOrder = i
		R.Root.Size = UDim2.new(1, 0, 0, R.Root.Size.Y.Offset)
		R.name.Text = tostring(g.Name or ("game " .. i))
		R.name.TextTruncate = Enum.TextTruncate.AtEnd
		R.sel.Visible = false
		rows[g] = R
		local b = click(R.Root, function() win:Select(g) end)
		Library:Connect(b.MouseEnter, function() if selected ~= g then tween(R.Root, { BackgroundColor3 = Library.Theme["Element Hover"] }) end end)
		Library:Connect(b.MouseLeave, function() if selected ~= g then tween(R.Root, { BackgroundColor3 = Library.Theme.Element }) end end)
	end

	-- inject: OnInject runs in its own thread; Enter in the key box does the same
	local function inject()
		if busy or not selected then return end
		local k = keyNow()
		if k == "" then
			win:SetStatus("enter your key", "bad")
			win:FlashField()
			return
		end
		if Data.OnInject then
			task.spawn(function()
				local ok, err = pcall(Data.OnInject, selected, k, win)
				if not ok then
					warn("[Allison Loader] " .. tostring(err))
					win:SetBusy(false)
					win:SetStatus("error", "bad")
				end
			end)
		end
	end
	Library:Connect(btn.MouseButton1Click, inject)
	Library:Connect(box.FocusLost, function(enter) if enter then inject() end end)

	-- in: the whole window fades in, grows to full size and rises a little
	local home = canvas.Position
	canvas.Position = home + UDim2.fromOffset(0, 12)
	if Library.Animations then
		tween(canvas, { GroupTransparency = 0 }, 0.35, Enum.EasingStyle.Quad)
		tween(scale, { Scale = 1 }, 0.45, Enum.EasingStyle.Back)
		tween(canvas, { Position = home }, 0.4)
	else
		canvas.GroupTransparency, scale.Scale, canvas.Position = 0, 1, home
	end
	refreshKey()
	if Data.Games and Data.Games[1] then win:Select(Data.Games[1]) end
	return win
end

return Library
